import { createWorkspace, teardownWorkspace, Workspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import * as fs from "fs/promises";

async function main() {
  const names = ["pool-agent-1", "pool-agent-2", "pool-agent-3", "pool-agent-4"];

  try {
    // Provision exactly four workspaces concurrently
    const createResults = await Promise.all(
      names.map((name) =>
        createWorkspace(name, {
          ttl: { days: 1 },
          credentials: { role: "Editor" },
        })
      )
    );

    const workspaces: Workspace[] = [];
    for (const res of createResults) {
      if (res.error) {
        throw res.error;
      }
      workspaces.push(res.data);
    }

    // Upload init.txt to each workspace
    await Promise.all(
      workspaces.map((workspace, index) => {
        const s3 = new S3Client({
          endpoint: "REDACTED",
          region: "REDACTED",
          credentials: {
            accessKeyId: workspace.credentials!.accessKeyId,
            secretAccessKey: workspace.credentials!.secretAccessKey,
          },
        });

        return s3.send(
          new PutObjectCommand({
            Bucket: workspace.bucket,
            Key: "init.txt",
            Body: names[index],
          })
        );
      })
    );

    // Write summary file
    const summary = workspaces.map((w, index) => ({
      name: names[index],
      bucket: w.bucket,
    }));
    await fs.writeFile(
      "/home/user/ws-pool/pool.json",
      JSON.stringify(summary, null, 2)
    );

    // Teardown
    await Promise.allSettled(
      workspaces.map((w) => teardownWorkspace(w))
    );

    process.exit(0);
  } catch (error) {
    console.error("Error:", error);
    process.exit(1);
  }
}

main();
